import {chromium} from 'playwright';

const URL = 'http://localhost:4173/';
const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1200, height: 760}, deviceScaleFactor: 1});
const errors = [];
const requests = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));
page.on('request', (r) => { if (r.url().endsWith('.js')) requests.push(r.url().replace(URL, '')); });

const chunksSoFar = () => requests.filter((u) => /Widget-|index-/.test(u)).map((u) => u.replace(/^assets\//, ''));

await page.goto(URL, {waitUntil: 'networkidle'});
await page.waitForSelector('.viz-widget__chart[data-engine="gravity-charts"] svg', {timeout: 15000});
await page.waitForTimeout(500);
console.log('after initial load:', chunksSoFar().join(', '));
await page.screenshot({path: '/tmp/pw/1-sales-light.png'});

// hover: crosshair + tooltip
const chart = await page.locator('.viz-widget__chart').boundingBox();
await page.mouse.move(chart.x + chart.width * 0.55, chart.y + chart.height * 0.45);
await page.waitForTimeout(400);
await page.screenshot({path: '/tmp/pw/2-sales-light-hover.png'});

const before = requests.length;
await page.getByRole('radio', {name: 'Мониторинг'}).click();
await page.waitForSelector('.viz-widget__chart[data-engine="yagr"] canvas', {timeout: 15000});
await page.waitForTimeout(800);
console.log('after switch to monitoring:', requests.slice(before).map((u) => u.replace(/^assets\//, '')).join(', '));
await page.screenshot({path: '/tmp/pw/3-monitoring-light.png'});
await page.mouse.move(chart.x + chart.width * 0.7, chart.y + chart.height * 0.5);
await page.waitForTimeout(400);
await page.screenshot({path: '/tmp/pw/4-monitoring-light-hover.png'});

await page.getByRole('checkbox', {name: 'Тёмная тема'}).click();
await page.waitForTimeout(600);
await page.mouse.move(5, 5);
await page.waitForTimeout(300);
await page.screenshot({path: '/tmp/pw/5-monitoring-dark.png'});

const before2 = requests.length;
await page.getByRole('radio', {name: 'Продажи'}).click();
await page.waitForSelector('.viz-widget__chart[data-engine="gravity-charts"] svg', {timeout: 15000});
await page.waitForTimeout(500);
console.log('after switch back to sales (new requests):', requests.slice(before2).length);
await page.screenshot({path: '/tmp/pw/6-sales-dark.png'});

await page.getByRole('checkbox', {name: 'Таблица'}).click();
await page.waitForTimeout(400);
await page.screenshot({path: '/tmp/pw/7-table-dark.png'});

console.log('footer:', (await page.locator('.viz-widget__footer').innerText()).replace(/\s+/g, ' '));
console.log('console errors/warnings:', errors.length ? '\n' + errors.join('\n') : 'none');
await browser.close();
EOF
sleep 2; cat /tmp/preview.log; cd /tmp/pw && timeout 120 node check.mjs

