page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));
await page.route(`${ORIGIN}/**`, async (route) => {
    const url = new URL(route.request().url());
    const path = url.pathname === '/' ? '/index.html' : url.pathname;
    const file = join(DIST, path);
    if (path.endsWith('.js')) requests.push(path.replace('/assets/', ''));
    if (!existsSync(file)) return route.fulfill({status: 404, body: 'not found'});
    return route.fulfill({status: 200, contentType: MIME[extname(file)] || 'application/octet-stream', body: readFileSync(file)});
});

const named = (list) => list.filter((u) => /Widget-|index-|isEmpty/.test(u));

await page.goto(`${ORIGIN}/`, {waitUntil: 'networkidle'});
await page.waitForSelector('.viz-widget__chart[data-engine="gravity-charts"] svg', {timeout: 20000});
