await page.screenshot({path: '/tmp/pw/3-monitoring-light.png'});
await page.mouse.move(chart.x + chart.width * 0.7, chart.y + chart.height * 0.5);
await page.waitForTimeout(500);
await page.screenshot({path: '/tmp/pw/4-monitoring-light-hover.png'});

await page.getByRole('checkbox', {name: 'Тёмная тема'}).click();
await page.mouse.move(5, 5);
await page.waitForTimeout(700);
await page.screenshot({path: '/tmp/pw/5-monitoring-dark.png'});

